/**
 * send-rental-started
 *
 * Fired when the first unlock of a self-pickup rental is detected.
 * Sends thank-you email + SMS with how-to guides link, safety reminder,
 * and the scheduled return deadline.
 */

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.45.4";
import { getCorsHeaders } from "./cors.ts";
import { sendEmail, sendSms } from "../_shared/notify.ts";
import { normalizeSiteUrl } from "../_shared/normalizeSiteUrl.ts";
import { formatPlainBookingTime } from "../_shared/formatBookingTime.ts";
import { getBookingWindow } from "../_shared/pinTiming.ts";

function makeJsonResponse(corsHeaders: Record<string, string>) {
  return (body: unknown, status = 200) =>
    new Response(JSON.stringify(body), {
      status,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
}

function formatFriendly(iso: string): string {
  try {
    return new Date(iso).toLocaleString("en-US", {
      timeZone: "America/Denver",
      weekday: "short",
      month: "short",
      day: "numeric",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
    });
  } catch {
    return iso;
  }
}

function buildEmailHTML(opts: {
  name: string;
  orderId: number | string;
  unlockAt: string;
  returnDeadline: string;
  portalUrl: string;
  guidesUrl: string;
}): string {
  const { name, orderId, unlockAt, returnDeadline, portalUrl, guidesUrl } = opts;
  return `<!DOCTYPE html>
<html><body style="margin:0;padding:0;background:#f3f4f6;font-family:Arial,sans-serif;">
  <div style="max-width:600px;margin:24px auto;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,0.08);">
    <div style="background:linear-gradient(135deg,#1e3a8a 0%,#3b82f6 100%);padding:36px 24px;text-align:center;">
      <h1 style="color:#ffffff;margin:0;font-size:26px;">Thank You for Renting With Us!</h1>
      <p style="color:#e0f2fe;margin:10px 0 0 0;">Order #${orderId}</p>
    </div>
    <div style="padding:28px 24px;color:#1f2937;line-height:1.55;">
      <p>Hi ${name || "there"},</p>
      <p>Thank you for using <strong>U-Fill Dumpsters</strong>. We recorded that you unlocked your rental at <strong>${unlockAt}</strong>.</p>
      <p>If you need help with hitching, loading, dumping, or anything else, visit your customer portal for how-to guides, videos, and other resources:</p>
      <p style="text-align:center;margin:24px 0;">
        <a href="${guidesUrl}" style="display:inline-block;background:#1e3a8a;color:#ffffff;padding:12px 22px;text-decoration:none;border-radius:8px;font-weight:bold;">Open How-To Guides</a>
      </p>
      <div style="background:#fef3c7;border:1px solid #f59e0b;border-radius:8px;padding:16px;margin:20px 0;">
        <p style="margin:0 0 8px 0;font-weight:bold;color:#92400e;">Safety &amp; return reminder</p>
        <p style="margin:0;color:#78350f;">Your rental period ends on <strong>${returnDeadline}</strong>. Please have everything loaded and secured under the lock by that time. Your access code remains valid for one extra hour after your scheduled end time.</p>
      </div>
      <p style="text-align:center;margin:24px 0;">
        <a href="${portalUrl}" style="display:inline-block;background:#3b82f6;color:#ffffff;padding:12px 22px;text-decoration:none;border-radius:8px;font-weight:bold;">Go to Customer Portal</a>
      </p>
      <p style="color:#6b7280;font-size:13px;">Questions? Reply to this email or contact us through your portal.</p>
      <p>Thank you again for choosing U-Fill Dumpsters!</p>
    </div>
  </div>
</body></html>`;
}

Deno.serve(async (req) => {
  const corsHeaders = getCorsHeaders(req);
  const jsonResponse = makeJsonResponse(corsHeaders);

  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const body = await req.json();
    const orderId = body.order_id ?? body.bookingId ?? body.booking_id;
    const unlockTimestamp = body.unlock_timestamp || new Date().toISOString();
    if (!orderId) {
      return jsonResponse({ success: false, error: "order_id required" }, 400);
    }

    const supabase = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
    );

    const { data: booking, error } = await supabase
      .from("bookings")
      .select("*, customers(*)")
      .eq("id", orderId)
      .single();
    if (error || !booking) {
      return jsonResponse({ success: false, error: error?.message || "Booking not found" }, 404);
    }

    if (booking.rental_started_notified_at) {
      return jsonResponse({
        success: true,
        skipped: true,
        reason: "already_notified",
        order_id: orderId,
      });
    }

    const siteUrl = normalizeSiteUrl(body.site_url || Deno.env.get("SITE_URL"));
    const portalUrl = `${siteUrl}/customer-portal`;
    const guidesUrl = `${siteUrl}/customer-portal?tab=guides`;
    const window = getBookingWindow(booking);
    const returnDeadline = booking.pickup_time_slot
      ? `${booking.pickup_date} ${formatPlainBookingTime(booking.pickup_time_slot) || booking.pickup_time_slot}`
      : formatFriendly(window.endIso);

    const customer = booking.customers || {};
    const name = booking.name || customer.name || "Customer";
    const email = booking.email || customer.email;
    const phone = booking.phone || customer.phone;
    const smsOptIn = customer.sms_opt_in !== false;

    const html = buildEmailHTML({
      name,
      orderId,
      unlockAt: formatFriendly(unlockTimestamp),
      returnDeadline,
      portalUrl,
      guidesUrl,
    });

    const emailResult = email
      ? await sendEmail(email, `You're all set — rental started (Order #${orderId})`, html)
      : { success: false, error: "No email" };

    const smsContent =
      `U-Fill Dumpsters: Thanks for renting with us! Your rental started at ${formatFriendly(unlockTimestamp)}. ` +
      `Return by ${returnDeadline} and lock securely. Guides: ${guidesUrl}`;
    const smsResult = await sendSms(phone, smsContent, { smsOptIn });

    const now = new Date().toISOString();
    await supabase
      .from("bookings")
      .update({ rental_started_notified_at: now })
      .eq("id", orderId);

    console.log("[send-rental-started] Done", { orderId, emailResult, smsResult });
    return jsonResponse({
      success: true,
      order_id: orderId,
      email: emailResult,
      sms: smsResult,
    });
  } catch (error) {
    console.error("[send-rental-started] Error:", error);
    return jsonResponse({
      success: false,
      error: error instanceof Error ? error.message : String(error),
    }, 500);
  }
});

const ALLOWED_HEADERS = 'authorization, x-client-info, apikey, content-type';
const ALLOWED_METHODS = 'GET, POST, PUT, PATCH, DELETE, OPTIONS';

function parseAllowedOrigins(): Set<string> {
  const raw = Deno.env.get('ALLOWED_ORIGINS') ?? '';
  return new Set(
    raw
      .split(',')
      .map((origin) => origin.trim())
      .filter(Boolean),
  );
}

let cachedOrigins: Set<string> | null = null;

function getAllowedOrigins(): Set<string> {
  if (!cachedOrigins) {
    cachedOrigins = parseAllowedOrigins();
  }
  return cachedOrigins;
}

/** Origin-aware CORS headers. Set ALLOWED_ORIGINS (comma-separated) in env. */
export function getCorsHeaders(req: Request): Record<string, string> {
  const headers: Record<string, string> = {
    'Access-Control-Allow-Headers': ALLOWED_HEADERS,
    'Access-Control-Allow-Methods': ALLOWED_METHODS,
  };

  const origin = req.headers.get('Origin');
  if (origin && getAllowedOrigins().has(origin)) {
    headers['Access-Control-Allow-Origin'] = origin;
    headers['Vary'] = 'Origin';
  }

  return headers;
}

/**
 * Shared Brevo / Resend email + Brevo / Twilio SMS helpers.
 * SMS_PROVIDER env: "brevo" (default) | "twilio"
 */

const BREVO_API_KEY = Deno.env.get("BREVO_API_KEY");
const BREVO_FROM_EMAIL = Deno.env.get("BREVO_FROM_EMAIL") || "noreply@u-filldumpsters.com";
const BREVO_SMS_SENDER = Deno.env.get("BREVO_SMS_SENDER") || "UFillDump";
const RESEND_API_KEY = Deno.env.get("RESEND_API_KEY");
const SMS_PROVIDER = (Deno.env.get("SMS_PROVIDER") || "brevo").toLowerCase();
const TWILIO_ACCOUNT_SID = Deno.env.get("TWILIO_ACCOUNT_SID");
const TWILIO_AUTH_TOKEN = Deno.env.get("TWILIO_AUTH_TOKEN");
const TWILIO_FROM_NUMBER = Deno.env.get("TWILIO_FROM_NUMBER");

export type SendEmailResult = {
  success: boolean;
  provider?: string;
  error?: string;
  result?: unknown;
};

export type SendSmsResult = {
  success: boolean;
  provider?: string;
  skipped?: boolean;
  reason?: string;
  error?: string;
  result?: unknown;
};

/** Normalize to E.164-ish digits; assume US (+1) when 10 digits. */
export function normalizePhoneE164(phone: string | null | undefined): string | null {
  if (!phone) return null;
  const digits = phone.replace(/\D/g, "");
  if (digits.length === 10) return `+1${digits}`;
  if (digits.length === 11 && digits.startsWith("1")) return `+${digits}`;
  if (phone.trim().startsWith("+") && digits.length >= 10) return `+${digits}`;
  return null;
}

export async function sendEmail(
  toEmail: string,
  subject: string,
  htmlContent: string,
  maxRetries = 2,
): Promise<SendEmailResult> {
  let lastError: string | null = null;
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const ts = new Date().toISOString();
    try {
      if (BREVO_API_KEY) {
        const brevoResponse = await fetch("https://api.brevo.com/v3/smtp/email", {
          method: "POST",
          headers: {
            "api-key": BREVO_API_KEY,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            sender: { email: BREVO_FROM_EMAIL, name: "U-Fill Dumpsters" },
            to: [{ email: toEmail }],
            subject,
            htmlContent,
          }),
        });
        if (brevoResponse.ok) {
          const result = await brevoResponse.json();
          return { success: true, provider: "brevo", result };
        }
        lastError = `Brevo API error: ${await brevoResponse.text()}`;
        console.error(`[${ts}] [notify] Brevo email failed:`, lastError);
      }

      if (RESEND_API_KEY) {
        const resendResponse = await fetch("https://api.resend.com/emails", {
          method: "POST",
          headers: {
            Authorization: `Bearer ${RESEND_API_KEY}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            from: "U-Fill Dumpsters <noreply@u-filldumpsters.com>",
            to: [toEmail],
            subject,
            html: htmlContent,
          }),
        });
        if (resendResponse.ok) {
          const result = await resendResponse.json();
          return { success: true, provider: "resend", result };
        }
        lastError = `Resend API error: ${await resendResponse.text()}`;
        console.error(`[${ts}] [notify] Resend email failed:`, lastError);
      }

      if (!BREVO_API_KEY && !RESEND_API_KEY) {
        return { success: false, error: "No email service configured" };
      }

      if (attempt < maxRetries) {
        await new Promise((r) => setTimeout(r, Math.pow(2, attempt) * 1000));
      }
    } catch (err) {
      lastError = err instanceof Error ? err.message : String(err);
      console.error(`[${ts}] [notify] Email exception:`, lastError);
      if (attempt < maxRetries) {
        await new Promise((r) => setTimeout(r, Math.pow(2, attempt) * 1000));
      }
    }
  }
  return { success: false, error: lastError || "Unknown email error" };
}

async function sendSmsBrevo(toE164: string, content: string): Promise<SendSmsResult> {
  if (!BREVO_API_KEY) {
    return { success: false, error: "BREVO_API_KEY not configured" };
  }
  const res = await fetch("https://api.brevo.com/v3/transactionalSMS/sms", {
    method: "POST",
    headers: {
      "api-key": BREVO_API_KEY,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      sender: BREVO_SMS_SENDER.slice(0, 11),
      recipient: toE164,
      content,
      type: "transactional",
    }),
  });
  if (!res.ok) {
    return { success: false, provider: "brevo", error: await res.text() };
  }
  return { success: true, provider: "brevo", result: await res.json() };
}

async function sendSmsTwilio(toE164: string, content: string): Promise<SendSmsResult> {
  if (!TWILIO_ACCOUNT_SID || !TWILIO_AUTH_TOKEN || !TWILIO_FROM_NUMBER) {
    return { success: false, error: "Twilio env vars not configured" };
  }
  const auth = btoa(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`);
  const body = new URLSearchParams({
    To: toE164,
    From: TWILIO_FROM_NUMBER,
    Body: content,
  });
  const res = await fetch(
    `https://api.twilio.com/2010-04-01/Accounts/${TWILIO_ACCOUNT_SID}/Messages.json`,
    {
      method: "POST",
      headers: {
        Authorization: `Basic ${auth}`,
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body,
    },
  );
  if (!res.ok) {
    return { success: false, provider: "twilio", error: await res.text() };
  }
  return { success: true, provider: "twilio", result: await res.json() };
}

/**
 * Send an SMS. Skips when phone is missing or customer has opted out.
 * @param smsOptIn - when false, skip; when undefined/true, send
 */
export async function sendSms(
  phone: string | null | undefined,
  content: string,
  options: { smsOptIn?: boolean | null } = {},
): Promise<SendSmsResult> {
  if (options.smsOptIn === false) {
    return { success: true, skipped: true, reason: "sms_opt_out" };
  }
  const toE164 = normalizePhoneE164(phone);
  if (!toE164) {
    return { success: true, skipped: true, reason: "invalid_phone" };
  }

  try {
    if (SMS_PROVIDER === "twilio") {
      return await sendSmsTwilio(toE164, content);
    }
    return await sendSmsBrevo(toE164, content);
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

const DEFAULT_SITE_URL = "https://u-filldumpsters.com";

/** Resolve app origin for links in emails (request body → SITE_URL env → production default). */
export function normalizeSiteUrl(url?: string | null): string {
  const fallback = Deno.env.get("SITE_URL") || DEFAULT_SITE_URL;
  const candidate = url && url.trim().length > 0 ? url : fallback;

  try {
    const parsed = new URL(candidate);
    return `${parsed.origin}`.replace(/\/$/, "");
  } catch {
    return DEFAULT_SITE_URL;
  }
}

/**
 * Parse booking time slots stored as 24h (HH:mm / HH:mm:ss) or 12h (h:mm a).
 */
export function parseBookingTimeToDate(timeString: string): Date | null {
  if (!timeString || typeof timeString !== "string") return null;
  const trimmed = timeString.trim();
  if (!trimmed) return null;

  const ref = new Date(2000, 0, 1);

  const try24WithSeconds = /^(\d{1,2}):(\d{2}):(\d{2})$/.exec(trimmed);
  if (try24WithSeconds) {
    const d = new Date(ref);
    d.setHours(parseInt(try24WithSeconds[1], 10), parseInt(try24WithSeconds[2], 10), 0, 0);
    return d;
  }

  const try24 = /^(\d{1,2}):(\d{2})$/.exec(trimmed);
  if (try24 && !/\s*(AM|PM)/i.test(trimmed)) {
    const d = new Date(ref);
    d.setHours(parseInt(try24[1], 10), parseInt(try24[2], 10), 0, 0);
    return d;
  }

  const try12 = /^(\d{1,2}):(\d{2})\s*(AM|PM)$/i.exec(trimmed);
  if (try12) {
    let hours = parseInt(try12[1], 10);
    const minutes = parseInt(try12[2], 10);
    const meridiem = try12[3].toUpperCase();
    if (meridiem === "PM" && hours < 12) hours += 12;
    if (meridiem === "AM" && hours === 12) hours = 0;
    const d = new Date(ref);
    d.setHours(hours, minutes, 0, 0);
    return d;
  }

  return null;
}

export function formatBookingTime(
  timeString: string,
  options: { isSelfService?: boolean; isReturnBy?: boolean } = {},
): string {
  if (!timeString) return "N/A";
  const parsed = parseBookingTimeToDate(timeString);
  if (!parsed) return timeString;

  const formatted = parsed.toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  });

  if (options.isSelfService) {
    const hour24 = parsed.getHours();
    const minute = parsed.getMinutes();
    if (options.isReturnBy || hour24 >= 22 || (hour24 === 23 && minute === 0)) {
      return `by ${formatted}`;
    }
    if (hour24 <= 8 || (hour24 === 6 && minute === 0)) {
      return `after ${formatted}`;
    }
  }

  return formatted;
}

/** 12-hour time only (no "after" / "by" prefix) for copy that already includes those words. */
export function formatPlainBookingTime(timeString: string): string {
  if (!timeString) return "N/A";
  const parsed = parseBookingTimeToDate(timeString);
  if (!parsed) return timeString;
  return parsed.toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  });
}

export const PIN_LEAD_TIME_MS = 12 * 60 * 60 * 1000;
/** Extra hour the padlock PIN stays valid after the scheduled booking end. */
export const RETURN_GRACE_MS = 60 * 60 * 1000;

export type BookingWindowFields = {
  drop_off_date?: string | null;
  drop_off_time_slot?: string | null;
  pickup_date?: string | null;
  pickup_time_slot?: string | null;
};

/**
 * Parse a time slot like "6:00 AM" and convert MST -> UTC.
 * MST is UTC-6, so we add 6 hours. Falls back to fallbackHourUTC if unparseable.
 */
export function buildBookingDateUTC(
  date: string,
  timeSlot: string | null | undefined,
  fallbackHourUTC: number,
): string {
  const pad = (n: number) => String(n).padStart(2, "0");

  if (timeSlot) {
    const match = timeSlot.trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
    if (match) {
      let hour = parseInt(match[1], 10);
      const minute = parseInt(match[2], 10);
      const meridiem = match[3].toUpperCase();
      if (meridiem === "PM" && hour !== 12) hour += 12;
      if (meridiem === "AM" && hour === 12) hour = 0;
      const utcHour = hour + 6;
      if (utcHour >= 24) {
        const nextDay = new Date(date + "T00:00:00Z");
        nextDay.setUTCDate(nextDay.getUTCDate() + 1);
        const nextDayStr = nextDay.toISOString().split("T")[0];
        return `${nextDayStr}T${pad(utcHour - 24)}:${pad(minute)}:00+00:00`;
      }
      return `${date}T${pad(utcHour)}:${pad(minute)}:00+00:00`;
    }
  }

  return `${date}T${pad(fallbackHourUTC)}:00:00+00:00`;
}

/** Add RETURN_GRACE_MS to an ISO date string and return a new ISO (+00:00) string. */
export function addGraceHour(isoDate: string): string {
  const ms = new Date(isoDate).getTime() + RETURN_GRACE_MS;
  return new Date(ms).toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

export function getBookingWindow(booking: BookingWindowFields) {
  const startIso = buildBookingDateUTC(
    booking.drop_off_date ?? "",
    booking.drop_off_time_slot,
    12,
  );
  const endIso = buildBookingDateUTC(
    booking.pickup_date ?? "",
    booking.pickup_time_slot,
    5,
  );

  const startMs = new Date(startIso).getTime();
  const endMs = new Date(endIso).getTime();
  const graceEndMs = endMs + RETURN_GRACE_MS;
  const graceEndIso = new Date(graceEndMs).toISOString().replace(/\.\d{3}Z$/, "+00:00");

  return {
    startMs,
    endMs,
    graceEndMs,
    pinEligibleFromMs: startMs - PIN_LEAD_TIME_MS,
    startIso,
    endIso,
    graceEndIso,
  };
}

export function isWithinPinGenerationWindow(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  if (!booking.drop_off_date || !booking.pickup_date) return false;
  const { pinEligibleFromMs, graceEndMs } = getBookingWindow(booking);
  const nowMs = now.getTime();
  return nowMs >= pinEligibleFromMs && nowMs < graceEndMs;
}

export function isBookingEnded(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  if (!booking.pickup_date) return false;
  const { graceEndMs } = getBookingWindow(booking);
  return now.getTime() >= graceEndMs;
}

export function getPinWindowSkipReason(
  booking: BookingWindowFields,
  now: Date = new Date(),
): "too_early" | "ended" | null {
  if (!booking.drop_off_date || !booking.pickup_date) return "too_early";
  const { pinEligibleFromMs, graceEndMs } = getBookingWindow(booking);
  const nowMs = now.getTime();
  if (nowMs < pinEligibleFromMs) return "too_early";
  if (nowMs >= graceEndMs) return "ended";
  return null;
}
